const fs = require('fs');
const path = require('path');

// ============================================================
// generar_491_detalles_y_periodos.js
// ============================================================
// El chat aprende a contar EL DETALLE de cada registro, y a responder
// por el periodo que se le pida.
//
// 1. LOS DETALLES
//    Antes decia solo "vomito". Ahora dice QUE vomito y CUANTAS VECES,
//    que es lo que la persona marco y lo que el veterinario necesita:
//
//      Tú: ¿cuándo vomitó?
//      Chiqui: 4 veces en los últimos meses:
//              · 26 ago — vomitó (bilis, 2 veces)
//                 💬 "en la madrugada"
//              · 20 ago — vomitó (pasto, 1 vez)
//              · 15 jul — vomitó (espuma, 3 o más veces)
//
//    Los detalles ya se guardaban en las columnas *_detalle: el chat
//    simplemente no los leia.
//
//    Vale para todas las señales: el color de las heces, cuantos dias
//    sin defecar, cuantas comidas salto, desde cuando toma mas agua.
//
// 2. LOS PERIODOS
//    Ahora reconoce: este mes, 2 meses, trimestre, 6 meses, este año.
//    Y despues de responder OFRECE ampliar, porque quien pregunta por
//    vomitos suele querer saber si es algo nuevo o si viene de antes:
//
//      [su digestión en los últimos 3 meses] [en el último año]
//
//    Para eso el chat pasa a cargar 365 dias de historial en vez de 30.
//
// 3. Y EL RESUMEN PARA EL VETERINARIO tambien lleva los detalles.
//
// DOS BUGS QUE ENCONTRE PROBANDO
//   La ñ otra vez: escribi 'ultimo año' pero el texto ya viene
//   normalizado como "ultimo ano", asi que nunca calzaba.
//
//   "vomitó este año" caia en la pregunta de desambiguacion en vez de
//   responder. Ahora, si la pregunta trae un periodo, ya no es ambigua.
//
// Si algo no calza, ABORTA sin escribir NADA.
// ============================================================

const RUTA_CHAT = 'components/ChiquiChat.tsx';
const RUTA_FLOT = 'components/ChiquiFlotante.tsx';
const CHAT_B64 = '';
const FLOT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico NINGUN archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const dChat = path.join(process.cwd(), RUTA_CHAT);
const dFlot = path.join(process.cwd(), RUTA_FLOT);
for (const [r, d] of [[RUTA_CHAT, dChat], [RUTA_FLOT, dFlot]]) {
  if (!fs.existsSync(d)) abortar('no se encontro ' + r + '.');
}

const actual = fs.readFileSync(dChat, 'utf8');
if (actual.includes('s.detalle ?')) {
  abortar('el chat ya muestra los detalles. Parece que este script ya se corrio.');
}
if (!actual.includes("case 'notas'")) {
  abortar('falta el script 484. Correlo primero.');
}

const chat = Buffer.from(CHAT_B64, 'base64').toString('utf8');
const flot = Buffer.from(FLOT_B64, 'base64').toString('utf8');

for (const r of ['detalle?: string', 's.detalle ?', "'ultimo ano'", 'masAmplio', "'trimestre'"]) {
  if (!chat.includes(r)) abortar('el chat nuevo no incluye [' + r + ']. Script corrupto.');
}
// La ñ no puede volver a las frases de periodo.
if (chat.includes("'ultimo año'") || chat.includes("'este año'")) {
  abortar('las frases de periodo siguen con ñ: nunca calzarian.');
}
console.log('  OK  el chat muestra detalles y reconoce periodos');

for (const r of ['const DETALLE', 'detalle,', 'getDate() - 365']) {
  if (!flot.includes(r)) abortar('el flotante nuevo no incluye [' + r + ']. Script corrupto.');
}
console.log('  OK  el flotante trae los detalles y 365 dias');

fs.writeFileSync(dChat, chat, 'utf8');
console.log('');
console.log('OK: ' + RUTA_CHAT);
fs.writeFileSync(dFlot, flot, 'utf8');
console.log('OK: ' + RUTA_FLOT);
console.log('');
console.log('Prueba: "¿cuándo vomitó?", "vomitó este año" y');
console.log('"¿cómo han estado sus heces?".');
